"use client";
import Link from "next/link";
import { trackViewContent } from "@/lib/meta-pixel";
import { useEffect, useRef, useState } from "react";
import { ArrowRight, ArrowUpRight, Check, ChevronRight, RotateCcw, Truck } from "lucide-react";
import { ProductBundleOptions } from "./product-bundle-options";
import { bundleEstimate, isBundleEligible } from "@/lib/bundle-offer";
import { SHIPPING_NOTE, isComingSoon, isOrderable } from "@/lib/commerce-policy";
import { Accordion, AccordionItem, AccordionTrigger, AccordionContent } from "@/components/ui/accordion";
import { ProductGallery } from "./product-gallery";
import { productVisuals } from "@/lib/product-visuals";
import { packageContents } from "@/lib/product-art";
import { money, unitPrice, type Product } from "@/lib/catalog";
import { CartConnectionNotice, Quantity, useStore } from "./store-shell";
import { productContent } from "@/lib/product-content";
import { ProductStory } from "./product-story";
import { ProductEssentials } from "./product-essentials";
import { ProductSwitcher } from "./product-navigation";
import { ProductRail } from "./product-rail";
import { CustomerReviews, ProductReviewLink } from "./customer-reviews";
import skincareRange from "@/lib/skincare-range.json";
import { supplementDetails } from "@/lib/supplement-details";
import { SupplementFormula, SupplementDirections } from "./supplement-information";
import { ProductGuides } from "./buyer-paths";
import { STORE_POLICIES } from "@/lib/store-policies";
import "./purchase-clarity.css";

export { CollectionPage } from "./collection-page";

export function ProductPage({product:p,designPreview=false}:{product:Product;designPreview?:boolean}){
 const {add,products,mode,busy,ready}=useStore();
 const live=mode==="live";
 const comingSoon=isComingSoon(p)||!!p.pricePending;
 const skin=skincareRange.find(item=>item.id===p.id);
 const content=productContent[p.id];
 const [variantId,setVariantId]=useState(p.variants?.find(v=>v.available)?.id||p.variants?.[0]?.id||"");
 const variant=p.variants?.find(v=>v.id===variantId);
 const [quantity,setQuantity]=useState(1);
 const available=!comingSoon&&p.available!==false&&variant?.available!==false&&!p.requiresSellingPlan;
 const supplement=supplementDetails[p.id];
 const price=variant?.price??unitPrice(p);
 const currency=variant?.currency||p.currency||"USD";
 // Bundle eligible products show the tiers; the add button shows this selection's own estimate.
 const bundle=p.category==="supplements"&&isBundleEligible(p.id);
 const estimate=bundle?bundleEstimate(price,quantity):{gross:Math.round(price*100)*quantity/100,total:Math.round(price*100)*quantity/100,saved:0};
 useEffect(()=>{
  if(live&&variantId&&!comingSoon)trackViewContent({variantId,name:p.name,price,currency});
 },[live,variantId,comingSoon,p.name,price,currency]);
 const purchaseFirst=!comingSoon;
 const inlineCta=useRef<HTMLDivElement>(null);
 const [inlineCtaInView,setInlineCtaInView]=useState(true);
 useEffect(()=>{
  const row=inlineCta.current;
  if(!purchaseFirst||!row||typeof IntersectionObserver==="undefined")return;
  const observer=new IntersectionObserver(([entry])=>setInlineCtaInView(entry.isIntersecting||entry.boundingClientRect.top>0));
  observer.observe(row);
  return()=>observer.disconnect();
 },[purchaseFirst,comingSoon]);
 const related=products.filter(other=>other.category===p.category&&other.id!==p.id);
 const addSelection=()=>add(p.id,quantity,variantId);
 const addLabel=<>{!available?"Currently unavailable":busy?"Updating…":"Add to bag"} <span>{estimate.saved>0&&<s>{money(estimate.gross,currency)}</s>}{money(estimate.total,currency)}</span></>;
 const gallery=<ProductGallery key={p.id} product={p}/>;
 const summary=<><div className="product-summary"><p className="eyebrow">{p.category.toUpperCase()} / {p.type.toUpperCase()}</p><div className="product-title-row"><h1>{p.name}</h1></div>{<p className="product-size">{variant?.title&&variant.title!=="Default Title"?variant.title:packageContents(p)}{p.ritual&&<> <span>·</span> {p.ritual}</>}</p>}</div><ProductReviewLink productId={p.id} designPreview={designPreview&&mode==="preview"}/></>;
 const productInfo=<>{content&&<p className="product-summary-description">{productVisuals[p.id]?.lead || content.description}</p>}{content&&<ul className="product-highlights">{content.highlights.slice(0,3).map(highlight=><li key={highlight}><Check size={15}/><span>{highlight}</span></li>)}</ul>}<p className={`product-current-price${comingSoon?" price-pending":""}`}>{comingSoon?"Coming soon":money(price,currency)}</p><ProductEssentials product={p} price={price} currency={currency}/></>;
 const purchaseControls=<>{!comingSoon&&p.variants&&p.variants.length>1?<div className="product-variant-picker"><label htmlFor="product-variant">Select option</label><select id="product-variant" value={variantId} onChange={e=>setVariantId(e.target.value)}>{p.variants.map(v=><option key={v.id} value={v.id}>{v.title}{!v.available?", sold out":""}</option>)}</select></div>:p.size&&<div className="product-format"><span>FORMAT</span><strong>{p.size}</strong><Check size={15}/></div>}{!comingSoon&&<>
 {available&&<ProductBundleOptions quantity={quantity} setQuantity={setQuantity} price={price} currency={currency} bundleEligible={bundle}/>}
 <CartConnectionNotice/>
 <div className="add-to-bag-row" ref={inlineCta}><Quantity value={quantity} setValue={setQuantity} label={p.name} disabled={busy||!available}/><button className="button button-dark" disabled={busy||!ready||!available} onClick={addSelection}>{addLabel}</button></div>
 {!live&&<p className="product-preview-note">Orders will open shortly.</p>}
 {purchaseFirst&&isOrderable(p,mode)&&<ul className="purchase-assurance">
  <li><Truck size={15} aria-hidden="true"/><span>Shipping usually takes 3 to 5 days. Cost shown at checkout. <a href={STORE_POLICIES.shipping.href}>Shipping policy</a></span></li>
  <li><RotateCcw size={15} aria-hidden="true"/><span>Unopened, unused products can be returned within 30 days of delivery. <a href={STORE_POLICIES.refund.href}>Returns</a></span></li>
 </ul>}
 </>}
 {comingSoon&&<div className="product-launch-note skincare-launch-note"><p className="launch-status">Coming soon</p><p>Explore the ingredients, application steps and product details ahead of launch. Skincare is not available to order yet.</p><button className="button button-dark full-width" disabled>Not available to order yet</button><Link href="/collections/supplements" className="under-link">Explore supplements <ArrowUpRight size={16}/></Link></div>}</>;
 // Coming-soon pages keep the original single-panel order.
 const panelTop=<>{summary}{productInfo}{purchaseControls}</>;
 const panelRest=<>
 {/* Targets exist only in the editorial ProductStory; generic Shopify products have none. */}
 {content&&<div className="product-jump-links"><a href="#product-formula">Explore ingredients <ArrowRight size={14}/></a>{content.routine&&<a href="#product-routine">How to use <ArrowRight size={14}/></a>}</div>}<Accordion type="single" collapsible className="product-accordion"><AccordionItem value="details"><AccordionTrigger>Product details</AccordionTrigger><AccordionContent><p>{p.description}</p><dl><div><dt>Collection</dt><dd>{p.category}</dd></div><div><dt>Format</dt><dd>{packageContents(p)}</dd></div>{p.ritual&&<div><dt>Step / focus</dt><dd>{p.ritual}</dd></div>}{supplement&&<><div><dt>Made in</dt><dd>{supplement.country}</dd></div>{supplement.flavor&&<div><dt>Flavor</dt><dd>{supplement.flavor}</dd></div>}{supplement.netWeight&&<div><dt>Net weight</dt><dd>{supplement.netWeight}</dd></div>}<div><dt>Contents</dt><dd>{supplement.contents}</dd></div></>}</dl>{!live&&!supplement&&!skin&&<p>{p.pricePending?"The final label will include serving size, ingredients and directions before orders open.":"This skincare collection is in development. The final formula and application directions will be published before launch."}</p>}</AccordionContent></AccordionItem>{(!live||skin||supplement)&&<><AccordionItem value="formula"><AccordionTrigger>{p.category==="skincare"?"Ingredients & formulation":"Ingredients & listed amounts"}</AccordionTrigger><AccordionContent>{skin?<p><strong>Key ingredients:</strong> {skin.ingredients}. Refer to the packaging for the current ingredient list.</p>:supplement?<SupplementFormula details={supplement} productId={p.id}/>:<>The full ingredient list and {p.category==="skincare"?"formula details":"Supplement Facts panel"} will be available before orders open.</>}</AccordionContent></AccordionItem><AccordionItem value="use"><AccordionTrigger>How to use</AccordionTrigger><AccordionContent>{skin?<p>{skin.directions}</p>:supplement?<SupplementDirections details={supplement}/>:<>{p.category==="skincare"?`The proposed place for ${p.name} is the ${p.ritual.toLowerCase()} step. `:""}Follow the approved product label for amounts and frequency when the collection launches.</>}</AccordionContent></AccordionItem></>}{/* The shipping window applies only to something a shopper can order now (not coming soon, sold out or preview). */}{isOrderable(p,mode)&&<AccordionItem value="shipping"><AccordionTrigger>Shipping</AccordionTrigger><AccordionContent>{SHIPPING_NOTE}</AccordionContent></AccordionItem>}</Accordion><ProductGuides product={p}/></>;
 return <main id="main" className={`product-page${purchaseFirst?" purchase-first":""}`}><ProductSwitcher product={p} products={products}/><nav className="breadcrumbs product-breadcrumbs section-pad" aria-label="Breadcrumb"><Link href="/">IQON</Link><ChevronRight size={12}/><Link href={`/collections/${p.category}`}>{p.category}</Link><ChevronRight size={12}/><span>{p.name}</span></nav><section id="overview" className={`product-detail section-pad ${p.category==="supplements"?"supplied-product-detail":"skincare-product-detail"}`}>{purchaseFirst
  // The gallery leads the DOM so phones show the product first and the keyboard order matches.
  // Desktop keeps its two-column composition, and its visual order, by grid placement.
  ?<>{gallery}<div className="purchase-panel purchase-panel-summary">{summary}</div><div className="purchase-panel purchase-panel-info">{productInfo}</div><div className="purchase-panel purchase-panel-buy">{purchaseControls}</div><div className="purchase-panel purchase-panel-details">{panelRest}</div></>
  :<>{gallery}<div className="purchase-panel">{panelTop}{panelRest}</div></>}</section>
 {content?<ProductStory product={p} products={products}/>:<section className={`pdp-editorial ${p.pricePending?"supplied-editorial":""}`}><img src={p.campaign} alt={`The IQON ${p.category} collection in the studio`} width={1920} height={1080} loading="lazy"/><div><p className="eyebrow">CONSIDERED, TO THE LAST DETAIL</p><h2>{p.category==="skincare"?<>A place for<br/>every step.</>:<>Make room for<br/>the everyday.</>}</h2><p>{p.category==="skincare"?"A focused collection brings the first cleanse, treatment and moisturizing steps into one point of view.":"A considered routine starts with clarity. Explore the collection, compare the formats and find the essentials that fit your everyday."}</p><Link className="under-link" href="/approach">Our approach <ArrowUpRight size={16}/></Link></div></section>}
 <CustomerReviews productId={p.id} productName={p.name} designPreview={designPreview&&mode==="preview"}/><section className="related-products section-pad"><div className="section-heading"><div><p className="eyebrow">EXPLORE THE COLLECTION</p><h2>{p.category==="skincare"?"Complete your ritual.":"Explore more supplements."}</h2></div><Link href={`/collections/${p.category}`} className="under-link">{p.category==="skincare"?"Explore skincare":"Shop supplements"} <ArrowUpRight size={16}/></Link></div><ProductRail products={related} label={p.category}/></section>{isOrderable(p,mode)&&<div className={`sticky-purchase${purchaseFirst&&inlineCtaInView?" inline-cta-in-view":""}`}><div><img src={p.image} alt=""/><span>{p.name}<small>{packageContents(p)}</small></span></div><button className="button button-dark" disabled={busy||!ready||!available} onClick={addSelection}>{addLabel}</button></div>}</main>;
}

"use client";
import Link from "next/link";
import { ArrowRight, ArrowUpRight } from "lucide-react";
import { useStore } from "./store-shell";
import { ProductRail } from "./product-rail";
import { JournalPreview } from "./editorial";
import { CommunityReviews } from "./community-reviews";
import { customerReviews } from "@/lib/reviews";

export function IQONSite(){
 const {products}=useStore();
 const supplements=products.filter(p=>p.category==="supplements");
 const featured=supplements.find(p=>p.id==="colostrum-powder")||supplements[0];
 const edit=["colostrum-powder","creatine-monohydrate","hydrolyzed-collagen-peptides"].flatMap(id=>supplements.filter(p=>p.id===id));
 const creatine=supplements.find(p=>p.id==="creatine-monohydrate");
 const reviews=customerReviews.filter(review=>supplements.some(p=>p.id===review.productId));
 return <main id="main" className="iqon-home premium-home">
  <section className="home-opening section-pad">
   <div className="home-opening-copy"><p className="eyebrow">IQON SUPPLEMENTS</p><h1>Make room for <br/>feeling your best.</h1><p>Creatine for your training. Collagen for your favorite drink. Daily nutrients in capsules and gummies. Discover supplements that fit the way you live.</p><Link href="/collections/supplements" className="button button-dark">Shop supplements<ArrowRight size={18}/></Link><Link href="/approach" className="home-learning-link">Meet IQON<ArrowUpRight size={15}/></Link></div>
   {featured&&<Link className="home-opening-image" href={`/products/${featured.id}`} aria-label={`Explore ${featured.name}`}><img src={featured.image} alt={`IQON ${featured.name} packaging`} width={1122} height={1402} fetchPriority="high"/><span>{featured.name}<ArrowUpRight size={20}/></span></Link>}
  </section>
  <section className="featured section-pad commerce-featured home-edit" id="collection"><div className="section-heading"><div><h2>Find your starting point.</h2><p>A small edit from the collection, from your training session to your daily drink.</p></div><Link href="/collections/supplements" className="under-link">All supplements<ArrowRight size={18}/></Link></div><ProductRail products={edit}/></section>
  {creatine&&<section className="home-feature section-pad"><img src="/images/supplement-materials-v1/creatine-monohydrate.webp" alt="White powder in a metal scoop on a charcoal surface" width={1122} height={1402} loading="lazy"/><div><p className="eyebrow">CREATINE MONOHYDRATE</p><h2>Support the<br/>strength you build.</h2><p>For the sets, sprints and sessions you keep showing up for. Creatine monohydrate supports repeated, high intensity exercise alongside training.*</p><p className="home-fact-note">Unflavored, with no added caffeine or sweeteners. Each serving provides 5 g of creatine monohydrate. Follow the full loading and maintenance directions.</p><Link href={`/products/${creatine.id}`} className="under-link">Explore creatine<ArrowUpRight size={18}/></Link><p className="home-claim-note">*These statements have not been evaluated by the Food and Drug Administration. This product is not intended to diagnose, treat, cure, or prevent any disease.</p></div></section>}
  <section className="home-standards section-pad"><h2>Your day.<br/>Your preferences.</h2><div><article><h3>Keep it simple.</h3><p>Choose single ingredient creatine or unflavored collagen when you want a powder without added flavors or sweeteners.</p></article><article><h3>Find a flavor you enjoy.</h3><p>Explore chocolate collagen with cocoa and stevia, or passion fruit gummies with vitamins and minerals.</p></article><article><h3>Choose your format.</h3><p>A powder to mix, a capsule with water or a gummy to chew. Each product has its own directions and ingredients.</p></article><Link className="under-link" href="/approach">Our approach<ArrowUpRight size={16}/></Link></div></section>
  {featured?.id==="colostrum-powder"&&<section className="home-preparation section-pad"><div><p className="eyebrow">COLOSTRUM POWDER</p><h2>A cold drink.<br/>A measured scoop.</h2><p>Mix one scoop with 6 to 8 oz of cold water or your favorite beverage. Consume within ten minutes of preparing.</p><p className="home-fact-note">Contains milk. For adults. Read the complete directions and warnings before use.</p><Link href="/products/colostrum-powder#product-routine" className="under-link">See how to prepare it<ArrowUpRight size={16}/></Link></div><img src="/images/product-editorial/colostrum-powder.webp" alt="IQON Colostrum Powder beside a cold drink and a scoop of powder" width={1122} height={1402} loading="lazy"/></section>}
  <JournalPreview/>
  {reviews.length>0&&<CommunityReviews category="supplements" products={supplements} reviews={reviews}/>}
  <section className="home-shop-end section-pad"><div><h2>Find your formula.</h2><p>Explore the full supplement collection and preview the skincare range.</p></div><Link href="/collections/all" className="button button-dark">Shop all<ArrowRight size={18}/></Link></section>
 </main>;
}

import Link from "next/link";
import { ArrowRight, ArrowUpRight, BookOpen, Pill, Clock3, Droplets, Dumbbell, FlaskConical, Layers2, Leaf, Ruler, Sparkles, Waves } from "lucide-react";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { type Product, productPrice } from "@/lib/catalog";
import { productContent } from "@/lib/product-content";
import { supplementDetails, supplementDisclaimer } from "@/lib/supplement-details";
import { researchReading } from "@/lib/research-reading";
import { supplementVisualContent } from "@/lib/supplement-visual-content";
import { SupplementIngredientExplorer } from "./supplement-ingredient-explorer";
import { SupplementDirections, SupplementFormula } from "./supplement-information";

const icons={strength:Dumbbell,powder:Waves,drop:Droplets,leaf:Leaf,layers:Layers2,capsule:Pill,clock:Clock3,measure:Ruler,spark:Sparkles,flask:FlaskConical};

export function SupplementProductStory({product:p,comparison}:{product:Product;comparison:Product[]}) {
  const visual=supplementVisualContent[p.id];
  const copy=productContent[p.id];
  const details=supplementDetails[p.id];
  if(!visual||!copy||!details) return null;
  const research=copy.education;
  const reading=researchReading[p.id];

  return <div className="product-experience supplement-pdp-story skin-visual-story">
    <nav className="pdp-section-nav" aria-label="Product information"><a href="#product-benefits">The benefits</a><a href="#product-formula">Inside the formula</a><a href="#product-routine">Your routine</a>{research&&<a href="#ingredient-science">The research</a>}<a href="#compare">Find your fit</a><a href="#product-questions">FAQs</a><a href="#reviews">Reviews</a></nav>

    <section id="product-benefits" className="skin-story-section skin-story-benefits" aria-labelledby="benefits-heading">
      <div className="skin-benefits-editorial">
        <div className="skin-benefits-copy"><p className="skin-kicker">{visual.eyebrow}</p><h2 id="benefits-heading">{visual.title}</h2><p className="skin-benefits-intro">{visual.introduction}</p>
          <div className="skin-benefit-points">{visual.benefits.map(benefit=>{const Icon=icons[benefit.icon];return <article key={benefit.title}><Icon size={27} strokeWidth={1.2} aria-hidden="true"/><h3>{benefit.title}</h3><p>{benefit.body}</p></article>;})}</div>
        </div>
        <figure className="skin-benefits-photo"><img src={`/images/supplement-materials-v1/${p.id}.webp`} alt={visual.imageAlt} width={1122} height={1402} loading="lazy" decoding="async"/><span className="skin-photo-label">{visual.photoLabel}</span><figcaption>{visual.photoCaption}</figcaption></figure>
      </div>
    </section>

    <section id="product-formula" className="skin-story-section skin-story-formula" aria-labelledby="formula-heading">
      <header className="skin-section-title"><p className="skin-kicker">INSIDE THE FORMULA</p><h2 id="formula-heading">{visual.formulaTitle}</h2></header>
      <SupplementIngredientExplorer key={p.id} ingredients={copy.ingredients!} visuals={visual.ingredients} facts={visual.facts}/>
      {visual.composition?<div className="supp-composition" aria-label="Formula composition"><div><p className="skin-kicker">READING THE FORMULA</p><h3>{visual.composition.total}</h3><p>{visual.composition.note}</p></div><div className="supp-composition-measure"><div><strong>{visual.composition.percent}%</strong><span>{visual.composition.label}</span></div><div className="supp-composition-track" aria-hidden="true"><span style={{width:`${visual.composition.percent}%`}}/></div><p>Proportion within the total</p></div></div>:copy.ingredients!.length>1&&<dl className="supp-fact-strip">{visual.facts.map(fact=><div key={fact.label}><dt>{fact.label}</dt><dd><strong>{fact.value}</strong><span>{fact.detail}</span></dd></div>)}</dl>}
      <Accordion type="single" collapsible className="skin-formulation-accordion"><AccordionItem value="formula"><AccordionTrigger>Ingredients, listed amounts & allergen details</AccordionTrigger><AccordionContent><SupplementFormula details={details} productId={p.id}/></AccordionContent></AccordionItem></Accordion>
    </section>

    <section id="product-routine" className="skin-story-section skin-story-routine" aria-labelledby="routine-heading">
      <header className="skin-application-heading"><div><p className="skin-kicker">YOUR DAILY ROUTINE</p><h2 id="routine-heading">{visual.routineTitle}</h2></div><span className="skin-timing-label"><Clock3 size={18} strokeWidth={1.2} aria-hidden="true"/>{visual.timing}</span></header>
      <div className="skin-application-board">
        <figure className="skin-application-photo"><img src={`/images/product-editorial/${p.id}.webp`} alt={`IQON ${p.name}, product editorial composition`} width={1122} height={1402} loading="lazy" decoding="async"/><figcaption><strong>{p.name}</strong><span>{details.contents}</span></figcaption></figure>
        <ol className="skin-application-steps">{copy.routine!.steps.map((step,i)=>{const Icon=icons[visual.stepIcons[i]];return <li key={step.title}><div className="skin-step-top"><span>0{i+1}</span><Icon size={38} strokeWidth={1} aria-hidden="true"/></div><h3>{step.title}</h3><p>{step.body}</p></li>;})}</ol>
      </div>
      <div className="skin-application-details"><p><strong>Keep in mind</strong>{visual.routineNote}</p><Accordion type="single" collapsible><AccordionItem value="directions"><AccordionTrigger>Read the complete directions & care</AccordionTrigger><AccordionContent><SupplementDirections details={details}/></AccordionContent></AccordionItem></Accordion></div>
    </section>

    {research&&<section id="ingredient-science" className="skin-story-section supp-research" aria-labelledby="research-heading"><div className="supp-research-heading"><BookOpen size={31} strokeWidth={1.1} aria-hidden="true"/><p className="skin-kicker">{research.eyebrow}</p><h2 id="research-heading">{research.title}</h2></div><div className="supp-research-copy">{reading?<dl className="research-reading">{[{label:"What was studied",value:reading.studied},{label:"What was found",value:reading.finding},{label:"How it relates to this formula",value:reading.relevance},{label:"What it cannot tell us",value:reading.limitation}].map(item=><div key={item.label}><dt>{item.label}</dt><dd>{item.value}</dd></div>)}</dl>:<p>{research.body}</p>}<div className="supp-research-links">{research.sources.map(source=><a key={source.url} href={source.url} target="_blank" rel="noopener noreferrer"><span>{source.label}</span><ArrowUpRight size={17} aria-hidden="true"/></a>)}</div><p className="supp-research-scope">{research.scope}</p></div></section>}

    <section className="skin-story-section product-quality-note" aria-labelledby="quality-heading"><h2 id="quality-heading">Made in the {details.country}.</h2><p>{p.name} comes in {details.contents}. Keep the jar for its label, storage instructions and batch details. For a question about your product, <Link href="/help">contact IQON</Link> with the product name and batch number.</p></section>

    <section id="compare" className="skin-story-section skin-story-compare" aria-labelledby="comparison-heading">
      <div className="skin-routine-heading"><div><p className="skin-kicker">THE IQON SUPPLEMENT EDIT</p><h2 id="comparison-heading">Compare other<br/>IQON formulas.</h2></div><div><p>Explore the ingredients, format and price of other products in the collection.</p><Link href="/collections/supplements" className="skin-story-link">Explore the collection <ArrowUpRight size={17}/></Link></div></div>
      <p className="skin-compare-scroll-hint">Swipe to compare <ArrowRight size={14} aria-hidden="true"/></p>
      <div className="skin-compare-scroll" role="region" aria-label="Compare supplement formulas" tabIndex={0}>
        <table className="skin-compare-table"><caption className="sr-only">Compare {comparison.map(q=>q.name).join(", ")}</caption>
          <thead><tr><th scope="col"><span>AT A GLANCE</span></th>{comparison.map(q=><th key={q.id} scope="col" className={q.id===p.id?"skin-current":""}><Link href={q.id===p.id?"#overview":`/products/${q.id}`} className="skin-compare-product"><div className="skin-compare-image">{q.id===p.id&&<span className="skin-viewing">YOU’RE VIEWING</span>}<img src={q.image} alt={q.name} width={320} height={400} loading="lazy" decoding="async"/></div><h3>{q.name}</h3><p>{productPrice(q)}<span>{supplementDetails[q.id]?.contents}</span></p></Link></th>)}</tr></thead>
          <tbody>{[
            {label:"Focus",value:(q:Product)=>productContent[q.id]?.comparison?.focus||q.descriptor},
            {label:"Routine",value:(q:Product)=>productContent[q.id]?.comparison?.routine},
            {label:"Formula",value:(q:Product)=>productContent[q.id]?.comparison?.difference}
          ].map(row=><tr key={row.label}><th scope="row">{row.label}</th>{comparison.map(q=><td key={q.id} className={q.id===p.id?"skin-current":""}>{row.value(q)}</td>)}</tr>)}
          <tr className="skin-compare-actions"><th scope="row"><span className="sr-only">Explore</span></th>{comparison.map(q=><td key={q.id} className={q.id===p.id?"skin-current":""}><Link href={q.id===p.id?"#overview":`/products/${q.id}`}>{q.id===p.id?"Back to product":"Explore formula"}<ArrowUpRight size={15}/></Link></td>)}</tr></tbody>
        </table>
      </div>
      <p className="skin-comparison-note">These formulas are shown to help you compare. They are not a recommendation to take them together; choose according to your needs and healthcare professional’s advice.</p>
    </section>

